class Solution {
public:
    std::vector<int> productQueries(int n, std::vector<std::vector<int>>& queries) {
        const int MOD = 1e9 + 7;
        std::vector<int> powers;
        for (int b = 0; b < 32; b++) {
            if ((n >> b) & 1) powers.push_back(1 << b);
        }

        std::vector<int> res;
        res.reserve(queries.size());
        for (const auto& q : queries) {
            long long cur = 1;
            for (int i = q[0]; i <= q[1]; i++) {
                cur = (cur * powers[i]) % MOD;
            }
            res.push_back(cur);
        }
        return res;
    }
};

class Solution {
    public int[] productQueries(int n, int[][] queries) {
        int MOD = 1_000_000_007;
        java.util.List<Integer> powers = new java.util.ArrayList<>();
        for (int b = 0; b < 32; b++) {
            if (((n >> b) & 1) == 1) powers.add(1 << b);
        }

        int[] res = new int[queries.length];
        for (int q = 0; q < queries.length; q++) {
            long cur = 1;
            for (int i = queries[q][0]; i <= queries[q][1]; i++) {
                cur = (cur * powers.get(i)) % MOD;
            }
            res[q] = (int) cur;
        }
        return res;
    }
}

var productQueries = function(n, queries) {
    const MOD = 1000000007n;
    const powers = [];
    for (let b = 0; b < 32; b++) {
        if ((n >> b) & 1) powers.push(BigInt(1 << b));
    }

    return queries.map(([left, right]) => {
        let cur = 1n;
        for (let i = left; i <= right; i++) {
            cur = (cur * powers[i]) % MOD;
        }
        return Number(cur);
    });
};
